import{z as l,x as n,o as t,c as B,q as e,j as r,D as E,d as i,s,S as o}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"晶体管密度度量","description":"","frontmatter":{"title":"晶体管密度度量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/transistor-density-metric.md","filePath":"litho/transistor-density-metric.md","lastUpdated":1791063341000}'),d={name:"litho/transistor-density-metric.md"};function p(D,a,m,_,h,c){const A=n("Mermaid");return t(),B("div",null,[a[2]||(a[2]=e('<h1 id="晶体管密度度量" tabindex="-1">晶体管密度度量 <a class="header-anchor" href="#晶体管密度度量" aria-label="Permalink to &quot;晶体管密度度量&quot;">​</a></h1><div class="epigraph"><p>MTr/mm²、NAND2 等效、SRAM 位密度是三种口径；只报其中最大的那张图，比较会偏。</p><footer>—— 对照逻辑密度度量与 SRAM 密度分报的公开惯例</footer></div><p><a href="/litho/cpp-mmp">上一课</a>给出 CPP 与 MMP。缺口是把尺子合成「密度」时口径不一。本课钉晶体管密度度量。IRDS 如何官方化这些趋势，留给<a href="/litho/irds-roadmap">下一课</a>。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种常见：高压/高性能库的晶体管密度；NAND2 标准单元等效密度；SRAM 位元密度。助推器与轨道对它们影响不同：埋电源可能大幅改逻辑密度、少改 SRAM。光刻层数与 EUV 插入对 BEOL 密度（布线资源）的影响也不落在同一口径。</p><p>缺口是<strong>口径</strong>，不是再定义 CPP。把 SRAM 密度当逻辑节点进步，或把宣传峰值密度当全芯片可布密度，都会错估光刻负担。</p><p><span class="marginnote">NAND2 等效翻译成大白话：把一个标准「与非门」当标准砖头，其他单元按占地面积折算成多少块砖，密度才能在不同工艺之间比较——否则与非门、触发器、大驱动管混着数，数字没有可比性。</span></p><p><span class="marginnote">砖密度可以类比楼面图纸：图纸上最多能塞多少工位是峰值；真正摆进桌椅、留出走道后的工位数是可布密度。只报前者，就像用图纸容量夸出租率。</span></p>',8)),(t(),r(o,null,{default:E(()=>[s(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOGIC%5B%22%E9%80%BB%E8%BE%91%E6%99%B6%E4%BD%93%E7%AE%A1%E5%AF%86%E5%BA%A6%22%5D%20--%3E%20M1%5B%22%E5%88%86%E5%AD%90%3A%20%E6%99%B6%E4%BD%93%E7%AE%A1%E8%AE%A1%E6%95%B0%22%5D%0A%20%20NAND2%5B%22NAND2%20%E7%AD%89%E6%95%88%E5%AF%86%E5%BA%A6%22%5D%20--%3E%20M2%5B%22%E5%88%86%E5%AD%90%3A%20%E6%8A%98%E7%AE%97%20NAND2%20%E6%95%B0%22%5D%0A%20%20SRAM%5B%22SRAM%20%E4%BD%8D%E5%AF%86%E5%BA%A6%22%5D%20--%3E%20M3%5B%22%E5%88%86%E5%AD%90%3A%20%E4%BD%8D%E5%85%83%E6%95%B0%22%5D%0A%20%20M1%20--%3E%20D%5B%22%E5%88%86%E6%AF%8D%3A%20%E9%9D%A2%E7%A7%AF%E5%8F%A3%E5%BE%84%E4%B9%9F%E8%A6%81%E5%A3%B0%E6%98%8E%22%5D%0A%20%20M2%20--%3E%20D%0A%20%20M3%20--%3E%20D%0A%20%20D%20--%3E%20PIT%5B%22%E8%B7%A8%E5%8F%A3%E5%BE%84%E7%9B%B4%E6%8E%A5%E6%AF%94%E8%BE%83%3A%20%E4%BC%9A%E5%81%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全芯片可实现密度还含布线拥堵、电源网格、IP 空隙，低于砖的峰值。DTCO 必须报「砖」与「阻塞后」两层。3D 堆叠（CFET、键合）把密度改到垂直，平面 MTr/mm² 开始失效——后课会遇，本课先声明平面口径的边界。</p><p><span class="marginnote">ISSCC 对照有用，但各厂口径仍可能不一致。引用时写清是 SRAM 还是逻辑、是否含 dummy。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>密度 = 计数 / 面积。计数规则（是否含填充管、是否 SRAM）改变分子；面积是否含外围改变分母。光刻只约束面积能否印出，不定义计数规则——但比较光刻进步时必须固定规则。</p>',5)),(t(),r(o,null,{default:E(()=>[s(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20BRICK%5B%22%E5%8D%95%E5%85%83%20%2F%20SRAM%20%E7%A0%96%22%5D%20--%3E%20PEAK%5B%22%E5%B3%B0%E5%80%BC%E5%AF%86%E5%BA%A6%22%5D%0A%20%20ROUTE%5B%22%E6%8B%A5%E5%A0%B5%20%2F%20%E7%94%B5%E6%BA%90%22%5D%20--%3E%20CHIP%5B%22%E5%8F%AF%E5%B8%83%E5%AF%86%E5%BA%A6%22%5D%0A%20%20PEAK%20--%3E%20CMP%5B%22%E8%8A%82%E7%82%B9%E6%AF%94%E8%BE%83%E9%A1%BB%E5%A3%B0%E6%98%8E%E5%8F%A3%E5%BE%84%22%5D%0A%20%20CHIP%20--%3E%20CMP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造某节点 MTr/mm²。不把密度当功耗或性能。平面口径不描述 3D NAND 的比特密度。</p><p>后课默认：比较要写口径；下一课看 IRDS 用哪些表来约束光刻要求。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逻辑峰值、NAND2 等效、SRAM 是不同密度口径。</li><li>全芯片可布密度低于砖峰值。</li><li>引用公开对照时声明口径与年份。</li><li>出处：密度度量的公开惯例（ISSCC 对照传统）。</li></ul><p><span class="marginnote">常见误区：拿 SRAM 位密度当逻辑节点进步的指标。SRAM 单元与逻辑库对埋电源、BEOL 层数等改动的响应不同步，两者可能一升一平——引用时写清是哪一种口径、含不含 dummy。</span></p>',6))])}const T=l(d,[["render",p]]);export{M as __pageData,T as default};
